<script setup>
import { onMounted, ref } from 'vue';
const props = defineProps({ payload: { type: String, required: true } });
const state = JSON.parse(props.payload);
const application = state.application || {};
const rejectModal = ref(null);
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
onMounted(() => {
    if (state.view === 'show' && Object.keys(state.errors || {}).length && window.bootstrap?.Modal) {
        const element = document.getElementById('rejectSellerModal');
        if (element) window.bootstrap.Modal.getOrCreateInstance(element).show();
    }
});
</script>

<template>
<div :class="state.view==='index'?'dashboard-section seller-applications-page':'dashboard-section seller-application-details-page'">
    <template v-if="state.view==='index'">
        <div v-if="state.success" class="alert alert-success">{{state.success}}</div><div v-if="state.error" class="alert alert-danger">{{state.error}}</div>
        <div class="dashboard-panel mb-4"><div class="panel-header mb-0"><div><h5 class="mb-1">Seller Applications</h5><p class="text-muted mb-0 small">Review and manage users who want to become sellers.</p></div></div></div>
        <div class="row g-4 mb-4"><div v-for="item in [{label:'Total Applications',value:state.counts.total,style:'total',icon:'bi-file-earmark-text'},{label:'Pending',value:state.counts.pending,style:'pending',icon:'bi-hourglass-split'},{label:'Approved',value:state.counts.approved,style:'approved',icon:'bi-check-circle'},{label:'Rejected',value:state.counts.rejected,style:'rejected',icon:'bi-x-circle'}]" :key="item.label" class="col-xl-3 col-md-6"><div class="seller-application-stat-card"><div class="seller-application-stat-icon" :class="item.style"><i class="bi" :class="item.icon"></i></div><div class="seller-application-stat-content"><span>{{item.label}}</span><h3>{{item.value}}</h3></div></div></div></div>
        <div class="dashboard-panel mb-4"><form method="GET" :action="state.urls.index"><div class="seller-application-filters"><div class="seller-application-search"><i class="bi bi-search"></i><input type="text" name="search" :value="state.filters.search" placeholder="Search store, name or email..."></div><select name="status" class="seller-application-status-filter"><option value="">All Statuses</option><option value="pending" :selected="state.filters.status==='pending'">Pending</option><option value="approved" :selected="state.filters.status==='approved'">Approved</option><option value="rejected" :selected="state.filters.status==='rejected'">Rejected</option></select><button type="submit" class="seller-application-filter-btn"><i class="bi bi-search me-1"></i>Search</button><a :href="state.urls.index" class="seller-application-reset-btn" :hidden="!state.filters.search&&!state.filters.status"><i class="bi bi-arrow-counterclockwise"></i>Reset</a></div></form></div>
        <div class="dashboard-panel"><div class="panel-header"><div><h5 class="mb-1">Applications</h5><p class="text-muted mb-0 small">Review submitted seller applications.</p></div></div>
            <div v-if="state.applications.length" class="table-responsive seller-application-table-wrapper"><table class="table align-middle seller-application-table"><thead><tr><th>Applicant</th><th>Store</th><th>Contact</th><th>Status</th><th>Submitted</th><th class="text-end">Action</th></tr></thead><tbody>
                <tr v-for="item in state.applications" :key="item.id"><td><div class="seller-applicant"><div class="seller-applicant-avatar"><img v-if="item.applicant.photo" :src="item.applicant.photo" :alt="item.applicant.name"><span v-else>{{item.applicant.initial}}</span></div><div class="seller-applicant-info"><strong>{{item.applicant.name}}</strong><span>{{item.applicant.email}}</span></div></div></td><td><div class="seller-store-info"><i class="bi bi-shop"></i><span>{{item.store_name}}</span></div></td><td><div class="seller-contact-info"><span v-if="item.phone"><i class="bi bi-telephone me-1"></i>{{item.phone}}</span><span v-else class="text-muted">No phone</span><span v-if="item.address"><i class="bi bi-geo-alt me-1"></i>{{item.address.length>30?item.address.slice(0,27)+'...':item.address}}</span></div></td><td><span class="seller-application-badge" :class="item.status"><i class="bi" :class="item.status==='pending'?'bi-clock':item.status==='approved'?'bi-check-circle':'bi-x-circle'"></i>{{item.status}}</span></td><td><div class="seller-application-date"><strong>{{item.date}}</strong><span>{{item.time}}</span></div></td><td class="text-end"><a :href="item.show_url" class="seller-application-view-btn"><i class="bi bi-eye"></i>View</a></td></tr>
            </tbody></table></div>
            <div v-else class="seller-application-empty"><div class="seller-application-empty-icon"><i class="bi bi-inbox"></i></div><h5>No Applications Found</h5><p>There are no seller applications matching your current filters.</p><a :href="state.urls.index" class="seller-application-reset-btn" :hidden="!state.filters.search&&!state.filters.status"><i class="bi bi-arrow-counterclockwise me-1"></i>Clear Filters</a></div>
            <div v-if="state.pagination.links?.length>3" class="seller-application-pagination"><nav aria-label="Applications pagination"><a v-for="(link,index) in state.pagination.links" :key="index" :href="link.url||undefined" :class="{'active':link.active,'disabled':!link.url}" v-html="link.label"></a></nav></div>
        </div>
    </template>

    <template v-else>
        <div class="dashboard-panel mb-4"><div class="panel-header mb-0"><div><h5 class="mb-1">Seller Application</h5><p class="text-muted mb-0 small">Review the seller application details.</p></div><a :href="state.urls.index" class="seller-application-back-btn"><i class="bi bi-arrow-left"></i>Back to Applications</a></div></div>
        <div class="row g-4"><div class="col-lg-4"><div class="dashboard-panel seller-detail-card"><div class="seller-detail-card-header"><div class="seller-detail-icon"><i class="bi bi-person"></i></div><div><h5>Applicant</h5><span>User Information</span></div></div><div class="seller-profile"><div class="seller-profile-avatar"><img v-if="application.user.photo" :src="application.user.photo" :alt="application.user.name"><span v-else>{{application.user.initial}}</span></div><h4>{{application.user.name}}</h4><p>{{application.user.email}}</p></div><div class="seller-detail-list"><div class="seller-detail-item"><span><i class="bi bi-person-badge"></i>Username</span><strong>{{application.user.username||'—'}}</strong></div><div class="seller-detail-item"><span><i class="bi bi-telephone"></i>Phone</span><strong>{{application.user.phone||'—'}}</strong></div><div class="seller-detail-item"><span><i class="bi bi-geo-alt"></i>City</span><strong>{{application.user.city||'—'}}</strong></div><div class="seller-detail-item"><span><i class="bi bi-shield-check"></i>Account Status</span><strong class="seller-account-status" :class="application.user.status">{{application.user.status}}</strong></div></div></div></div>
            <div class="col-lg-8"><div class="dashboard-panel seller-detail-card"><div class="seller-detail-card-header"><div class="seller-detail-icon store"><i class="bi bi-shop"></i></div><div><h5>Store Application</h5><span>Submitted seller information</span></div></div><div class="seller-application-detail-status"><div><span class="seller-detail-label">Application Status</span><span class="seller-application-badge" :class="application.status"><i class="bi" :class="application.status==='pending'?'bi-clock':application.status==='approved'?'bi-check-circle':'bi-x-circle'"></i>{{application.status}}</span></div><div class="seller-submitted-date"><span>Submitted</span><strong>{{application.submitted}}</strong></div></div>
                <div class="seller-detail-field"><span class="seller-detail-label">Store Name</span><div class="seller-detail-value"><i class="bi bi-shop"></i>{{application.store_name}}</div></div><div class="seller-detail-field"><span class="seller-detail-label">Store Description</span><div class="seller-description-box">{{application.description||'No description provided.'}}</div></div><div class="row g-3"><div class="col-md-6"><div class="seller-detail-field"><span class="seller-detail-label">Phone Number</span><div class="seller-detail-value"><i class="bi bi-telephone"></i>{{application.phone||'Not provided'}}</div></div></div><div class="col-md-6"><div class="seller-detail-field"><span class="seller-detail-label">Address</span><div class="seller-detail-value"><i class="bi bi-geo-alt"></i>{{application.address||'Not provided'}}</div></div></div></div>
                <div v-if="application.status==='rejected'&&application.rejection_reason" class="seller-rejection-box"><div class="seller-rejection-title"><i class="bi bi-exclamation-circle"></i>Rejection Reason</div><p>{{application.rejection_reason}}</p></div><div v-if="application.reviewed" class="seller-reviewed-info"><i class="bi bi-check2-circle"></i><span>Reviewed on <strong>{{application.reviewed}}</strong></span></div>
                <div v-if="application.status==='pending'" class="seller-application-actions"><form :action="state.urls.approve" method="POST" class="seller-approve-form"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PATCH"><button type="submit" class="seller-approve-btn"><i class="bi bi-check-circle me-1"></i>Approve Application</button></form><button type="button" class="seller-reject-btn" data-bs-toggle="modal" data-bs-target="#rejectSellerModal"><i class="bi bi-x-circle me-1"></i>Reject Application</button></div>
            </div></div></div>
        <div v-if="application.status==='pending'" class="modal fade seller-reject-modal" id="rejectSellerModal" tabindex="-1" aria-labelledby="rejectSellerModalLabel" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title" id="rejectSellerModalLabel">Reject Seller Application</h5><p class="mb-0">Please provide a reason for rejection.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><form :action="state.urls.reject" method="POST"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PATCH"><div class="modal-body"><label for="rejection_reason" class="form-label">Rejection Reason <span class="text-danger">*</span></label><textarea id="rejection_reason" name="rejection_reason" class="form-control" rows="5" maxlength="2000" placeholder="Explain why this seller application is being rejected..." required>{{state.old.rejection_reason}}</textarea><small v-for="error in state.errors.rejection_reason" :key="error" class="text-danger d-block mt-2">{{error}}</small></div><div class="modal-footer"><button type="button" class="seller-modal-cancel-btn" data-bs-dismiss="modal">Cancel</button><button type="submit" class="seller-modal-reject-btn"><i class="bi bi-x-circle me-1"></i>Reject Application</button></div></form></div></div></div>
    </template>
</div>
</template>
